import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.2
.target sm_89
.address_size 64
// Optimization: register-block two horizontally adjacent output points
// per paired thread. The cooperative CTA tile grows from 8x16 to 16x16
// outputs while each thread retains four output channels and carries
// eight FP32 accumulators. Adjacent stride-4 windows reuse both the
// staged weights and overlapping aligned input vectors, halving the
// shared-memory load traffic per output while preserving ascending
// ic/ky/kx accumulation order for every output channel.
.visible .entry conv2d_3x96_k11_s4_p2(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 total_elems
)
{
    .reg .pred %p, %q;
    .reg .u32 %r_tid, %r_cta, %r_tw, %r_th, %r_ocp, %r_n, %r_half, %r_pair;
    .reg .u32 %r_tmp, %r_tmp2, %r_idx, %r_row, %r_col, %r_addr;
    .reg .u32 %r_sy, %r_sxp, %r_sx0, %r_sx1, %r_oy, %r_ox0, %r_ox1, %r_oc0;
    .reg .u32 %r_inb, %r_sbase, %r_sin, %r_saddr, %r_waddr, %r_ic, %r_ky;
    .reg .u32 %r_sinw, %r_wbase, %r_ocw, %r_rem;
    .reg .s32 %s_h0, %s_w0, %s_ih, %s_iw;
    .reg .u64 %rd_in, %rd_wt, %rd_bias, %rd_out, %rd_addr, %rd_off;
    .reg .f32 %f_acc0, %f_acc1, %f_acc2, %f_acc3;
    .reg .f32 %f_acc4, %f_acc5, %f_acc6, %f_acc7;
    .reg .f32 %f_a;
    .reg .f32 %f_u0, %f_u1, %f_u2, %f_u3;
    .reg .f32 %f_u4, %f_u5, %f_u6, %f_u7;
    .reg .f32 %f_u8, %f_u9, %f_u10, %f_u11;
    .reg .f32 %f_u12, %f_u13, %f_u14, %f_u15;
    .reg .f32 %f_b0, %f_b1, %f_b2, %f_b3;
    .shared .align 16 .f32 smem_in[5112];
    .shared .align 16 .f32 smem_wt[1056];
    ld.param.u64 %rd_in, [in_ptr];
    ld.param.u64 %rd_wt, [wt_ptr];
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_cta, %ctaid.x;
    // decompose ctaid.x: tw in [0,4), th in [0,4), ocp in [0,12), n
    rem.u32 %r_tw, %r_cta, 4;
    div.u32 %r_tmp, %r_cta, 4;
    rem.u32 %r_th, %r_tmp, 4;
    div.u32 %r_tmp, %r_tmp, 4;
    rem.u32 %r_ocp, %r_tmp, 12;
    div.u32 %r_n, %r_tmp, 12;
    mov.u32 %r_sin, smem_in;
    mov.u32 %r_sinw, smem_wt;
    // input halo origin for a 16x16 output tile: th*64-2, tw*64-2
    shl.b32 %r_tmp, %r_th, 6;
    cvt.s32.u32 %s_h0, %r_tmp;
    sub.s32 %s_h0, %s_h0, 2;
    shl.b32 %r_tmp, %r_tw, 6;
    cvt.s32.u32 %s_w0, %r_tmp;
    sub.s32 %s_w0, %s_w0, 2;
    // each adjacent thread pair splits eight channels; each thread covers
    // two horizontally adjacent spatial outputs
    and.b32 %r_half, %r_tid, 1;
    shr.u32 %r_pair, %r_tid, 1;
    shr.u32 %r_sy, %r_pair, 3;
    and.b32 %r_sxp, %r_pair, 7;
    shl.b32 %r_sx0, %r_sxp, 1;
    add.u32 %r_sx1, %r_sx0, 1;
    shl.b32 %r_oy, %r_th, 4;
    add.u32 %r_oy, %r_oy, %r_sy;
    shl.b32 %r_ox0, %r_tw, 4;
    add.u32 %r_ox0, %r_ox0, %r_sx0;
    add.u32 %r_ox1, %r_ox0, 1;
    // shared input base for the left point: sy*288 + sx0*4 elements
    mul.lo.u32 %r_inb, %r_sy, 288;
    shl.b32 %r_tmp, %r_sx0, 2;
    add.u32 %r_inb, %r_inb, %r_tmp;
    shl.b32 %r_sbase, %r_inb, 2;
    add.u32 %r_sbase, %r_sbase, %r_sin;
    // global element base for this CTA's eight adjacent output channels
    mul.lo.u32 %r_wbase, %r_ocp, 2904;
    mov.f32 %f_acc0, 0f00000000;
    mov.f32 %f_acc1, 0f00000000;
    mov.f32 %f_acc2, 0f00000000;
    mov.f32 %f_acc3, 0f00000000;
    mov.f32 %f_acc4, 0f00000000;
    mov.f32 %f_acc5, 0f00000000;
    mov.f32 %f_acc6, 0f00000000;
    mov.f32 %f_acc7, 0f00000000;
    mov.u32 %r_ic, 0;
L_ic:
    setp.ge.u32 %p, %r_ic, 3;
    @%p bra L_ic_done;
    // global element offset of channel start: (n*3 + ic)*50176
    mul.lo.u32 %r_tmp, %r_n, 3;
    add.u32 %r_tmp, %r_tmp, %r_ic;
    mul.lo.u32 %r_tmp, %r_tmp, 50176;
    // cooperative staging of the 71x71 halo tile for this channel
    mov.u32 %r_idx, %r_tid;
L_stage:
    setp.ge.u32 %p, %r_idx, 5041;
    @%p bra L_stage_done;
    div.u32 %r_row, %r_idx, 71;
    rem.u32 %r_col, %r_idx, 71;
    mul.lo.u32 %r_addr, %r_row, 72;
    add.u32 %r_addr, %r_addr, %r_col;
    shl.b32 %r_addr, %r_addr, 2;
    add.u32 %r_addr, %r_addr, %r_sin;
    cvt.s32.u32 %s_ih, %r_row;
    add.s32 %s_ih, %s_ih, %s_h0;
    cvt.s32.u32 %s_iw, %r_col;
    add.s32 %s_iw, %s_iw, %s_w0;
    mov.f32 %f_a, 0f00000000;
    setp.lt.s32 %p, %s_ih, 0;
    setp.ge.s32 %q, %s_ih, 224;
    or.pred %p, %p, %q;
    setp.lt.s32 %q, %s_iw, 0;
    or.pred %p, %p, %q;
    setp.ge.s32 %q, %s_iw, 224;
    or.pred %p, %p, %q;
    @%p bra L_stage_store;
    cvt.u32.s32 %r_tmp2, %s_ih;
    mul.lo.u32 %r_tmp2, %r_tmp2, 224;
    add.u32 %r_tmp2, %r_tmp2, %r_tmp;
    cvt.u32.s32 %r_row, %s_iw;
    add.u32 %r_tmp2, %r_tmp2, %r_row;
    cvt.u64.u32 %rd_off, %r_tmp2;
    shl.b64 %rd_off, %rd_off, 2;
    add.u64 %rd_addr, %rd_in, %rd_off;
    ld.global.f32 %f_a, [%rd_addr];
L_stage_store:
    st.shared.f32 [%r_addr], %f_a;
    add.u32 %r_idx, %r_idx, 256;
    bra L_stage;
L_stage_done:
    // cooperative staging of the 8x121 weights for this channel
    mov.u32 %r_idx, %r_tid;
L_wstage:
    setp.ge.u32 %p, %r_idx, 968;
    @%p bra L_wstage_done;
    div.u32 %r_ocw, %r_idx, 121;
    rem.u32 %r_rem, %r_idx, 121;
    div.u32 %r_row, %r_rem, 11;
    rem.u32 %r_col, %r_rem, 11;
    // Global OIHW element offset: wbase + ocw*363 + ic*121 + ky*11 + kx
    mul.lo.u32 %r_tmp2, %r_ocw, 363;
    add.u32 %r_tmp2, %r_tmp2, %r_wbase;
    mul.lo.u32 %r_addr, %r_ic, 121;
    add.u32 %r_tmp2, %r_tmp2, %r_addr;
    add.u32 %r_tmp2, %r_tmp2, %r_rem;
    cvt.u64.u32 %rd_off, %r_tmp2;
    shl.b64 %rd_off, %rd_off, 2;
    add.u64 %rd_addr, %rd_wt, %rd_off;
    ld.global.f32 %f_a, [%rd_addr];
    mul.lo.u32 %r_tmp2, %r_ocw, 132;
    mul.lo.u32 %r_addr, %r_row, 12;
    add.u32 %r_tmp2, %r_tmp2, %r_addr;
    add.u32 %r_tmp2, %r_tmp2, %r_col;
    shl.b32 %r_tmp2, %r_tmp2, 2;
    add.u32 %r_tmp2, %r_tmp2, %r_sinw;
    st.shared.f32 [%r_tmp2], %f_a;
    add.u32 %r_idx, %r_idx, 256;
    bra L_wstage;
L_wstage_done:
    bar.sync 0;
    mov.u32 %r_saddr, %r_sbase;
    mov.u32 %r_waddr, %r_sinw;
    mul.lo.u32 %r_tmp, %r_half, 2112;
    add.u32 %r_waddr, %r_waddr, %r_tmp;
    // Accumulate the two adjacent outputs' eight channel halves.
    // u0..u15 are the union of both stride-4 shifted 11-tap windows.
    mov.u32 %r_ky, 0;
L_ky:
    setp.ge.u32 %p, %r_ky, 11;
    @%p bra L_ky_done;
    ld.shared.v4.f32 {%f_u0, %f_u1, %f_u2, %f_u3}, [%r_saddr];
    ld.shared.v4.f32 {%f_u4, %f_u5, %f_u6, %f_u7}, [%r_saddr+16];
    ld.shared.v4.f32 {%f_u8, %f_u9, %f_u10, %f_u11}, [%r_saddr+32];
    ld.shared.v4.f32 {%f_u12, %f_u13, %f_u14, %f_u15}, [%r_saddr+48];
    // taps (ky,0) through (ky,3)
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr];
    fma.rn.f32 %f_acc0, %f_u0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc0, %f_u1, %f_b1, %f_acc0;
    fma.rn.f32 %f_acc0, %f_u2, %f_b2, %f_acc0;
    fma.rn.f32 %f_acc0, %f_u3, %f_b3, %f_acc0;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+528];
    fma.rn.f32 %f_acc1, %f_u0, %f_b0, %f_acc1;
    fma.rn.f32 %f_acc1, %f_u1, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc1, %f_u2, %f_b2, %f_acc1;
    fma.rn.f32 %f_acc1, %f_u3, %f_b3, %f_acc1;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+1056];
    fma.rn.f32 %f_acc2, %f_u0, %f_b0, %f_acc2;
    fma.rn.f32 %f_acc2, %f_u1, %f_b1, %f_acc2;
    fma.rn.f32 %f_acc2, %f_u2, %f_b2, %f_acc2;
    fma.rn.f32 %f_acc2, %f_u3, %f_b3, %f_acc2;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+1584];
    fma.rn.f32 %f_acc3, %f_u0, %f_b0, %f_acc3;
    fma.rn.f32 %f_acc3, %f_u1, %f_b1, %f_acc3;
    fma.rn.f32 %f_acc3, %f_u2, %f_b2, %f_acc3;
    fma.rn.f32 %f_acc3, %f_u3, %f_b3, %f_acc3;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr];
    fma.rn.f32 %f_acc4, %f_u4, %f_b0, %f_acc4;
    fma.rn.f32 %f_acc4, %f_u5, %f_b1, %f_acc4;
    fma.rn.f32 %f_acc4, %f_u6, %f_b2, %f_acc4;
    fma.rn.f32 %f_acc4, %f_u7, %f_b3, %f_acc4;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+528];
    fma.rn.f32 %f_acc5, %f_u4, %f_b0, %f_acc5;
    fma.rn.f32 %f_acc5, %f_u5, %f_b1, %f_acc5;
    fma.rn.f32 %f_acc5, %f_u6, %f_b2, %f_acc5;
    fma.rn.f32 %f_acc5, %f_u7, %f_b3, %f_acc5;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+1056];
    fma.rn.f32 %f_acc6, %f_u4, %f_b0, %f_acc6;
    fma.rn.f32 %f_acc6, %f_u5, %f_b1, %f_acc6;
    fma.rn.f32 %f_acc6, %f_u6, %f_b2, %f_acc6;
    fma.rn.f32 %f_acc6, %f_u7, %f_b3, %f_acc6;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+1584];
    fma.rn.f32 %f_acc7, %f_u4, %f_b0, %f_acc7;
    fma.rn.f32 %f_acc7, %f_u5, %f_b1, %f_acc7;
    fma.rn.f32 %f_acc7, %f_u6, %f_b2, %f_acc7;
    fma.rn.f32 %f_acc7, %f_u7, %f_b3, %f_acc7;
    // taps (ky,4) through (ky,7)
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+16];
    fma.rn.f32 %f_acc0, %f_u4, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc0, %f_u5, %f_b1, %f_acc0;
    fma.rn.f32 %f_acc0, %f_u6, %f_b2, %f_acc0;
    fma.rn.f32 %f_acc0, %f_u7, %f_b3, %f_acc0;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+544];
    fma.rn.f32 %f_acc1, %f_u4, %f_b0, %f_acc1;
    fma.rn.f32 %f_acc1, %f_u5, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc1, %f_u6, %f_b2, %f_acc1;
    fma.rn.f32 %f_acc1, %f_u7, %f_b3, %f_acc1;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+1072];
    fma.rn.f32 %f_acc2, %f_u4, %f_b0, %f_acc2;
    fma.rn.f32 %f_acc2, %f_u5, %f_b1, %f_acc2;
    fma.rn.f32 %f_acc2, %f_u6, %f_b2, %f_acc2;
    fma.rn.f32 %f_acc2, %f_u7, %f_b3, %f_acc2;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+1600];
    fma.rn.f32 %f_acc3, %f_u4, %f_b0, %f_acc3;
    fma.rn.f32 %f_acc3, %f_u5, %f_b1, %f_acc3;
    fma.rn.f32 %f_acc3, %f_u6, %f_b2, %f_acc3;
    fma.rn.f32 %f_acc3, %f_u7, %f_b3, %f_acc3;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+16];
    fma.rn.f32 %f_acc4, %f_u8, %f_b0, %f_acc4;
    fma.rn.f32 %f_acc4, %f_u9, %f_b1, %f_acc4;
    fma.rn.f32 %f_acc4, %f_u10, %f_b2, %f_acc4;
    fma.rn.f32 %f_acc4, %f_u11, %f_b3, %f_acc4;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+544];
    fma.rn.f32 %f_acc5, %f_u8, %f_b0, %f_acc5;
    fma.rn.f32 %f_acc5, %f_u9, %f_b1, %f_acc5;
    fma.rn.f32 %f_acc5, %f_u10, %f_b2, %f_acc5;
    fma.rn.f32 %f_acc5, %f_u11, %f_b3, %f_acc5;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+1072];
    fma.rn.f32 %f_acc6, %f_u8, %f_b0, %f_acc6;
    fma.rn.f32 %f_acc6, %f_u9, %f_b1, %f_acc6;
    fma.rn.f32 %f_acc6, %f_u10, %f_b2, %f_acc6;
    fma.rn.f32 %f_acc6, %f_u11, %f_b3, %f_acc6;
    ld.shared.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%r_waddr+1600];
    fma.rn.f32 %f_acc7, %f_u8, %f_b0, %f_acc7;
    fma.rn.f32 %f_acc7, %f_u9, %f_b1, %f_acc7;
    fma.rn.f32 %f_acc7, %f_u10, %f_b2, %f_acc7;
    fma.rn.f32 %f_acc7, %f_u11, %f_b3, %f_acc7;
    // taps (ky,8) and (ky,9)
    ld.shared.v2.f32 {%f_b0, %f_b1}, [%r_waddr+32];
    fma.rn.f32 %f_acc0, %f_u8, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc0, %f_u9, %f_b1, %f_acc0;
    ld.shared.v2.f32 {%f_b0, %f_b1}, [%r_waddr+560];
    fma.rn.f32 %f_acc1, %f_u8, %f_b0, %f_acc1;
    fma.rn.f32 %f_acc1, %f_u9, %f_b1, %f_acc1;
    ld.shared.v2.f32 {%f_b0, %f_b1}, [%r_waddr+1088];
    fma.rn.f32 %f_acc2, %f_u8, %f_b0, %f_acc2;
    fma.rn.f32 %f_acc2, %f_u9, %f_b1, %f_acc2;
    ld.shared.v2.f32 {%f_b0, %f_b1}, [%r_waddr+1616];
    fma.rn.f32 %f_acc3, %f_u8, %f_b0, %f_acc3;
    fma.rn.f32 %f_acc3, %f_u9, %f_b1, %f_acc3;
    ld.shared.v2.f32 {%f_b0, %f_b1}, [%r_waddr+32];
    fma.rn.f32 %f_acc4, %f_u12, %f_b0, %f_acc4;
    fma.rn.f32 %f_acc4, %f_u13, %f_b1, %f_acc4;
    ld.shared.v2.f32 {%f_b0, %f_b1}, [%r_waddr+560];
    fma.rn.f32 %f_acc5, %f_u12, %f_b0, %f_acc5;
    fma.rn.f32 %f_acc5, %f_u13, %f_b1, %f_acc5;
    ld.shared.v2.f32 {%f_b0, %f_b1}, [%r_waddr+1088];
    fma.rn.f32 %f_acc6, %f_u12, %f_b0, %f_acc6;
    fma.rn.f32 %f_acc6, %f_u13, %f_b1, %f_acc6;
    ld.shared.v2.f32 {%f_b0, %f_b1}, [%r_waddr+1616];
    fma.rn.f32 %f_acc7, %f_u12, %f_b0, %f_acc7;
    fma.rn.f32 %f_acc7, %f_u13, %f_b1, %f_acc7;
    // tap (ky,10)
    ld.shared.f32 %f_b0, [%r_waddr+40];
    fma.rn.f32 %f_acc0, %f_u10, %f_b0, %f_acc0;
    ld.shared.f32 %f_b0, [%r_waddr+568];
    fma.rn.f32 %f_acc1, %f_u10, %f_b0, %f_acc1;
    ld.shared.f32 %f_b0, [%r_waddr+1096];
    fma.rn.f32 %f_acc2, %f_u10, %f_b0, %f_acc2;
    ld.shared.f32 %f_b0, [%r_waddr+1624];
    fma.rn.f32 %f_acc3, %f_u10, %f_b0, %f_acc3;
    ld.shared.f32 %f_b0, [%r_waddr+40];
    fma.rn.f32 %f_acc4, %f_u14, %f_b0, %f_acc4;
    ld.shared.f32 %f_b0, [%r_waddr+568];
    fma.rn.f32 %f_acc5, %f_u14, %f_b0, %f_acc5;
    ld.shared.f32 %f_b0, [%r_waddr+1096];
    fma.rn.f32 %f_acc6, %f_u14, %f_b0, %f_acc6;
    ld.shared.f32 %f_b0, [%r_waddr+1624];
    fma.rn.f32 %f_acc7, %f_u14, %f_b0, %f_acc7;
    // advance one padded input row and one padded weight row
    add.u32 %r_saddr, %r_saddr, 288;
    add.u32 %r_waddr, %r_waddr, 48;
    add.u32 %r_ky, %r_ky, 1;
    bra L_ky;
L_ky_done:
    bar.sync 0;
    add.u32 %r_ic, %r_ic, 1;
    bra L_ic;
L_ic_done:
    // epilogue: add bias and store both adjacent spatial points
    ld.param.u64 %rd_bias, [bias_ptr];
    ld.param.u64 %rd_out, [out_ptr];
    shl.b32 %r_oc0, %r_ocp, 3;
    shl.b32 %r_tmp, %r_half, 2;
    add.u32 %r_oc0, %r_oc0, %r_tmp;
    cvt.u64.u32 %rd_off, %r_oc0;
    shl.b64 %rd_off, %rd_off, 2;
    add.u64 %rd_addr, %rd_bias, %rd_off;
    ld.global.f32 %f_b0, [%rd_addr];
